create or replace function public.krevuno_nearby_map(p_lat double precision,p_lng double precision,p_radius_miles integer default 50) returns table(marker_type text,id uuid,title text,latitude double precision,longitude double precision,distance_miles double precision,amount numeric,currency text,time_label text,media_url text,media_type text,public_url text) language sql stable security definer set search_path=public as $$ with p as (select greatest(1,least(coalesce(p_radius_miles,50),100))::double precision radius,p_lat::double precision center_lat,p_lng::double precision center_lng,greatest(0.15,abs(cos(radians(p_lat))))::double precision lon_factor), c as (select 'NEED'::text marker_type,n.id,n.title,n.latitude::double precision item_lat,n.longitude::double precision item_lng,n.budget amount,n.currency,coalesce(to_char(n.starts_at at time zone 'UTC','YYYY-MM-DD HH24:MI "UTC"'),case when n.duration_minutes is not null then n.duration_minutes::text||' min' else '' end) time_label,n.media_url,n.media_type,case when n.public_listing then '/jobs/'||n.id::text else null end public_url from public.vovyyvov_needs n,p where n.status='OPEN' and n.map_opt_in=true and n.latitude is not null and n.longitude is not null and n.latitude::double precision between p.center_lat-(p.radius/69.0) and p.center_lat+(p.radius/69.0) and n.longitude::double precision between p.center_lng-(p.radius/(69.0*p.lon_factor)) and p.center_lng+(p.radius/(69.0*p.lon_factor)) union all select 'WORKER',a.id,a.skill,a.latitude::double precision,a.longitude::double precision,a.minimum_amount,a.currency,coalesce(nullif(a.hours_text,''),case when a.available_now then 'Available now' else '' end),a.media_url,a.media_type,null::text from public.vovyyvov_availability a,p where a.active=true and a.map_opt_in=true and a.latitude is not null and a.longitude is not null and a.latitude::double precision between p.center_lat-(p.radius/69.0) and p.center_lat+(p.radius/69.0) and a.longitude::double precision between p.center_lng-(p.radius/(69.0*p.lon_factor)) and p.center_lng+(p.radius/(69.0*p.lon_factor)) union all select 'NEED',o.id,o.title,o.latitude::double precision,o.longitude::double precision,o.amount,o.currency,coalesce(to_char(o.starts_at at time zone 'UTC','YYYY-MM-DD HH24:MI "UTC"'),case when o.duration_minutes is not null then o.duration_minutes::text||' min' else '' end),o.media_url,o.media_type,case when o.public_listing then '/jobs/'||o.id::text else null end from public.vovyyvov_opportunities o,p where o.status='OPEN' and o.map_opt_in=true and o.source_need_id is null and o.latitude is not null and o.longitude is not null and o.latitude::double precision between p.center_lat-(p.radius/69.0) and p.center_lat+(p.radius/69.0) and o.longitude::double precision between p.center_lng-(p.radius/(69.0*p.lon_factor)) and p.center_lng+(p.radius/(69.0*p.lon_factor))), d as (select c.*,3958.7613*2*asin(sqrt(power(sin(radians((c.item_lat-p.center_lat)/2)),2)+cos(radians(p.center_lat))*cos(radians(c.item_lat))*power(sin(radians((c.item_lng-p.center_lng)/2)),2))) dist from c cross join p) select d.marker_type,d.id,d.title,round(d.item_lat::numeric,1)::double precision,round(d.item_lng::numeric,1)::double precision,round(d.dist::numeric,1)::double precision,d.amount,d.currency,d.time_label,d.media_url,d.media_type,d.public_url from d cross join p where d.dist<=p.radius order by d.dist asc limit 500; $$; grant execute on function public.krevuno_nearby_map(double precision,double precision,integer) to anon,authenticated;

create or replace function public.krevuno_public_job(p_id uuid) returns table(id uuid,title text,description text,amount numeric,currency text,city text,starts_at timestamptz,ends_at timestamptz,duration_minutes integer,date_posted timestamptz,valid_through timestamptz,media_url text,media_type text) language sql stable security definer set search_path=public as $$ select n.id,n.title,('Short-term opportunity posted on KREVUNO'||case when n.city is not null then ' in '||n.city else '' end||'.')::text,n.budget,n.currency,n.city,n.starts_at,n.ends_at,n.duration_minutes,n.created_at,coalesce(n.ends_at,n.created_at+interval '30 days'),n.media_url,n.media_type from public.vovyyvov_needs n where n.id=p_id and n.status='OPEN' and n.public_listing=true union all select o.id,o.title,('Short-term opportunity posted on KREVUNO'||case when o.city is not null then ' in '||o.city else '' end||'.')::text,o.amount,o.currency,o.city,o.starts_at,o.ends_at,o.duration_minutes,o.created_at,coalesce(o.ends_at,o.created_at+interval '30 days'),o.media_url,o.media_type from public.vovyyvov_opportunities o where o.id=p_id and o.status='OPEN' and o.public_listing=true and o.source_need_id is null limit 1; $$; grant execute on function public.krevuno_public_job(uuid) to anon,authenticated;